<!DOCTYPE html>
<html lang="zh-CN">

<head>
    <meta charset="UTF-8">
    <style>
        /* 引入字体：中文使用思源宋体(Noto Serif SC)提升文学感 */
        @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;700&family=Noto+Serif+SC:wght@300;400;700&display=swap');

        /* ====== 玻璃拟态容器 ====== */
        .glass-calendar-app {
            font-family: 'Noto Serif SC', 'Lato', sans-serif;
            width: 100%;
            max-width: 100%;
            margin: 10px 0;
            padding: 20px;
            line-height: 1.5;
            border-radius: 20px;
            position: relative;
            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
            box-sizing: border-box;

            /* === 玻璃拟态核心效果 === */
            backdrop-filter: blur(16px) saturate(180%);
            -webkit-backdrop-filter: blur(16px) saturate(180%);

            /* === 主题色变量（默认：薰衣草紫） === */
            --theme-primary: #8b7ec8;
            --theme-primary-rgb: 139, 126, 200;
            --theme-secondary: #a599d9;
            --theme-accent: #6c5cb0;

            /* === 事件类型颜色 === */
            --c-world: #9ca3af;
            --c-major: #d4b483;
            --c-user: #8eb8a3;
            --c-char: #c59f9f;

            /* === 浅色模式（默认） === */
            /* 均匀半透明毛玻璃 + 主题色混色 */
            --glass-bg: rgba(255, 255, 255, 0.75);
            --glass-tint: rgba(var(--theme-primary-rgb), 0.08);
            --glass-border: rgba(var(--theme-primary-rgb), 0.2);
            --glass-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
            --glass-inner-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.5);
            /* 清晰字体 */
            --text-primary: #1a1a1a;
            --text-secondary: #404040;
            --text-muted: #606060;
            /* 卡片透明不遮挡 */
            --card-bg: rgba(var(--theme-primary-rgb), 0.05);
            --card-hover: rgba(var(--theme-primary-rgb), 0.12);
            --card-active-bg: rgba(var(--theme-primary-rgb), 0.18);
            --divider-color: rgba(var(--theme-primary-rgb), 0.12);
            --shimmer-color: rgba(255, 255, 255, 0.4);
            --theme-glow: none;
        }

        /* === 深色模式 === */
        .glass-calendar-app.dark-mode {
            --glass-bg: rgba(20, 20, 30, 0.75);
            --glass-bg-solid: rgba(20, 20, 30, 0.75);
            --glass-border: rgba(var(--theme-primary-rgb), 0.25);
            /* 外围主题色光晕 */
            --glass-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
            --glass-inner-shadow: inset 0 1px 1px rgba(var(--theme-primary-rgb), 0.2);
            --text-primary: #f5f5f5;
            --text-secondary: #d0d0d0;
            --text-muted: #999999;
            --card-bg: rgba(var(--theme-primary-rgb), 0.08);
            --card-hover: rgba(var(--theme-primary-rgb), 0.15);
            --card-active-bg: rgba(var(--theme-primary-rgb), 0.28);
            --divider-color: rgba(var(--theme-primary-rgb), 0.2);
            --shimmer-color: rgba(var(--theme-primary-rgb), 0.1);
            --theme-glow: none;
        }

        /* === 主题色变体 === */
        /* 薰衣草紫 (默认) */
        .glass-calendar-app.theme-lavender {
            --theme-primary: #8b7ec8;
            --theme-primary-rgb: 139, 126, 200;
            --theme-secondary: #a599d9;
            --theme-accent: #6c5cb0;
        }

        /* 薄荷绿 */
        .glass-calendar-app.theme-mint {
            --theme-primary: #5fb9a0;
            --theme-primary-rgb: 95, 185, 160;
            --theme-secondary: #7fd4be;
            --theme-accent: #3d9980;
        }

        /* 珊瑚橘 */
        .glass-calendar-app.theme-coral {
            --theme-primary: #e8927c;
            --theme-primary-rgb: 232, 146, 124;
            --theme-secondary: #f5b4a3;
            --theme-accent: #d4705a;
        }

        /* 天空蓝 */
        .glass-calendar-app.theme-sky {
            --theme-primary: #6ba3d6;
            --theme-primary-rgb: 107, 163, 214;
            --theme-secondary: #8fc1eb;
            --theme-accent: #4a85b8;
        }

        /* 玫瑰粉 */
        .glass-calendar-app.theme-rose {
            --theme-primary: #d4869c;
            --theme-primary-rgb: 212, 134, 156;
            --theme-secondary: #e8a8b9;
            --theme-accent: #c06b82;
        }

        /* 琥珀金 */
        .glass-calendar-app.theme-amber {
            --theme-primary: #d4a54b;
            --theme-primary-rgb: 212, 165, 75;
            --theme-secondary: #e8c478;
            --theme-accent: #b88a30;
        }

        /* 应用玻璃效果 */
        .glass-calendar-app {
            background: var(--glass-bg);
            border: 1px solid var(--glass-border);
            box-shadow: var(--glass-shadow), var(--glass-inner-shadow), var(--theme-glow);
            color: var(--text-primary);
            overflow: hidden;
        }

        /* 浅色模式：均匀主题色叠加层 */
        .glass-calendar-app:not(.dark-mode)::after {
            content: '';
            position: absolute;
            inset: 0;
            border-radius: inherit;
            background: rgba(var(--theme-primary-rgb), 0.06);
            pointer-events: none;
            z-index: 0;
        }

        /* 确保内容在叠加层之上 */
        .glass-calendar-app>* {
            position: relative;
            z-index: 1;
        }

        /* 深色模式额外光晕层 */
        .glass-calendar-app.dark-mode::after {
            content: '';
            position: absolute;
            inset: 0;
            border-radius: inherit;
            background: transparent;
            box-shadow: inset 0 0 40px rgba(var(--theme-primary-rgb), 0.1);
            pointer-events: none;
            z-index: 0;
        }



        /* ====== 设置栏 ====== */
        .glass-settings {
            display: flex;
            justify-content: flex-end;
            gap: 8px;
            margin-bottom: 12px;
            flex-wrap: wrap;
        }

        .glass-toggle-btn {
            background: var(--card-bg);
            border: 1px solid var(--glass-border);
            border-radius: 10px;
            padding: 6px 12px;
            cursor: pointer;
            font-size: 0.75em;
            color: var(--text-secondary);
            backdrop-filter: blur(8px);
            transition: all 0.3s ease;
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .glass-toggle-btn:hover {
