    <script>
        (function () {
            const container = document.getElementById('glass-calendar-container');
            const modeToggle = document.getElementById('glass-mode-toggle');
            const themeDots = document.querySelectorAll('.glass-theme-dot');
            const rawDataContainer = document.getElementById('calendar-raw-data');

            // === 缓存键名 ===
            const STORAGE_KEY_MODE = 'glass-calendar-dark-mode';
            const STORAGE_KEY_THEME = 'glass-calendar-theme';

            // === 读取缓存的设置 ===
            let isDarkMode = localStorage.getItem(STORAGE_KEY_MODE) === 'true';
            let savedTheme = localStorage.getItem(STORAGE_KEY_THEME) || 'lavender';

            // === 应用缓存的深色模式 ===
            if (isDarkMode) {
                container.classList.add('dark-mode');
                modeToggle.querySelector('.mode-icon').textContent = '☀️';
                modeToggle.querySelector('.mode-text').textContent = '浅色';
                modeToggle.classList.add('active');
            }

            // === 应用缓存的主题色 ===
            container.classList.remove('theme-lavender', 'theme-mint', 'theme-coral', 'theme-sky', 'theme-rose', 'theme-amber');
            container.classList.add(`theme-${savedTheme}`);
            themeDots.forEach(d => {
                d.classList.toggle('active', d.dataset.theme === savedTheme);
            });

            // === 深色模式切换 ===
            modeToggle.addEventListener('click', () => {
                isDarkMode = !isDarkMode;
                container.classList.toggle('dark-mode', isDarkMode);
                modeToggle.querySelector('.mode-icon').textContent = isDarkMode ? '☀️' : '🌙';
                modeToggle.querySelector('.mode-text').textContent = isDarkMode ? '浅色' : '深色';
                modeToggle.classList.toggle('active', isDarkMode);
                localStorage.setItem(STORAGE_KEY_MODE, isDarkMode);
            });

            // === 主题色切换 ===
            themeDots.forEach(dot => {
                dot.addEventListener('click', () => {
                    const theme = dot.dataset.theme;
                    // 移除所有主题类
                    container.classList.remove('theme-lavender', 'theme-mint', 'theme-coral', 'theme-sky', 'theme-rose', 'theme-amber');
                    // 添加选中主题
                    container.classList.add(`theme-${theme}`);
                    // 更新活动状态
                    themeDots.forEach(d => d.classList.remove('active'));
                    dot.classList.add('active');
                    localStorage.setItem(STORAGE_KEY_THEME, theme);
                });
            });

            // === 日历数据解析 ===
            if (!rawDataContainer) return;
            const rawString = rawDataContainer.textContent.trim();

            const lines = rawString.split(/\r?\n/);
            const calendarData = [];
            let currentDayObj = null;

            lines.forEach(line => {
                line = line.trim();
                if (!line) return;
                if (line.startsWith('Date:')) {
                    const parts = line.replace('Date:', '').split('|').map(s => s.trim());
                    if (parts.length >= 1) {
                        currentDayObj = {
                            dateStr: parts[0],
                            dayName: parts[1] || '',
                            events: []
                        };
                        calendarData.push(currentDayObj);
                    }
                }
                else if (line.startsWith('Event:') && currentDayObj) {
                    const parts = line.replace('Event:', '').split('|').map(s => s.trim());
                    if (parts.length >= 5) {
                        currentDayObj.events.push({
                            type: parts[0],
                            title: parts[1],
                            desc: parts[2],
                            time: parts[3],
                            location: parts[4]
                        });
                    } else if (parts.length >= 4) {
                        currentDayObj.events.push({
                            type: parts[0],
                            title: parts[1],
                            desc: '',
                            time: parts[2],
                            location: parts[3]
                        });
                    }
                }
            });

            const scroller = document.getElementById('glass-scroller');
            const eventList = document.getElementById('glass-list');

            function getColorByType(type) {
                switch (type) {
                    case 'world': return 'var(--c-world)';
                    case 'major': return 'var(--c-major)';
                    case 'user': return 'var(--c-user)';
                    case 'character': return 'var(--c-char)';
                    default: return 'currentColor';
                }
            }

            function translateType(type) {
                switch (type.toLowerCase()) {
                    case 'world': return '世界';
                    case 'major': return '重要';
                    case 'user': return '日常';
                    case 'character': return '羁绊';
                    default: return '其他';
                }
            }

            function render() {
                scroller.innerHTML = '';
                calendarData.forEach((day, index) => {
                    const card = document.createElement('div');
                    card.className = `glass-date-item ${index === 0 ? 'active' : ''}`;

                    const dateParts = day.dateStr.split('/');
                    const dayNum = dateParts[dateParts.length - 1];

                    let dotsHtml = '';
                    day.events.forEach(ev => {
                        const color = getColorByType(ev.type);
                        dotsHtml += `<div class="glass-dot" style="background-color: ${color}"></div>`;
                    });

                    card.innerHTML = `
                        <span class="glass-day-name">${day.dayName}</span>
                        <span class="glass-day-num">${dayNum}</span>
                        <div class="glass-dots">${dotsHtml}</div>
                    `;

                    card.onclick = () => {
                        scroller.querySelectorAll('.glass-date-item').forEach(c => c.classList.remove('active'));
                        card.classList.add('active');
                        card.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
                        renderEvents(day);
                    };
                    scroller.appendChild(card);
                });

                if (calendarData.length > 0) {
                    renderEvents(calendarData[0]);
                } else {
                    eventList.innerHTML = '<div class="glass-empty">空空如也</div>';
                }
            }

            function renderEvents(dayData) {
                eventList.innerHTML = '';
                if (dayData.events.length === 0) {
                    eventList.innerHTML = '<div class="glass-empty">没有安排？好好休息吧</div>';
                    return;
                }

                dayData.events.forEach(ev => {
                    const item = document.createElement('div');
                    item.className = `glass-event type-${ev.type}`;

                    let typeLabel = translateType(ev.type);

                    const descHtml = ev.desc ? `<div class="glass-event-desc">${ev.desc}</div>` : '';
                    item.innerHTML = `
                        <div class="glass-event-meta">
                            <span>${ev.time}</span>
                            <span>•</span>
                            <span>${typeLabel}</span>
                        </div>
                        <div class="glass-event-title">${ev.title}</div>
                        ${descHtml}
                        <div class="glass-event-loc">@ ${ev.location}</div>
                    `;
                    eventList.appendChild(item);
                });
            }

            render();
        })();
    </script>
</body>

</html>
