            --divider-color: rgba(212, 175, 55, 0.25);

            /* 深色事件颜色调整 */
            --c-world: #a09080;
            --c-major: #e8c44a;
            --c-user: #8bc48b;
            --c-char: #d4909a;
        }

        /* 应用背景效果 */
        .gufeng-calendar-app {
            background: var(--paper-bg);
            border: var(--border-style) var(--border-color);
            box-shadow: var(--shadow);
            color: var(--text-primary);
            overflow: hidden;
            border-radius: 4px;
        }

        /* 纸张纹理叠加 */
        .gufeng-calendar-app::before {
            content: '';
            position: absolute;
            inset: 0;
            background: var(--paper-texture);
            pointer-events: none;
            opacity: 0.6;
        }

        /* 确保内容层级正确 */
        .gufeng-calendar-app>* {
            position: relative;
            z-index: 1;
        }

        /* 装饰性角花 */
        .gufeng-corner {
            position: absolute;
            width: 40px;
            height: 40px;
            opacity: 0.4;
            pointer-events: none;
        }

        .gufeng-corner::before,
        .gufeng-corner::after {
            content: '';
            position: absolute;
            background: var(--ink-primary);
        }

        .gufeng-corner.top-left {
            top: 8px;
            left: 8px;
        }

        .gufeng-corner.top-left::before {
            top: 0;
            left: 0;
            width: 20px;
            height: 2px;
        }

        .gufeng-corner.top-left::after {
            top: 0;
            left: 0;
            width: 2px;
            height: 20px;
        }

        .gufeng-corner.top-right {
            top: 8px;
            right: 8px;
        }

        .gufeng-corner.top-right::before {
            top: 0;
            right: 0;
            width: 20px;
            height: 2px;
        }

        .gufeng-corner.top-right::after {
            top: 0;
            right: 0;
            width: 2px;
            height: 20px;
        }

        .gufeng-corner.bottom-left {
            bottom: 8px;
            left: 8px;
        }

        .gufeng-corner.bottom-left::before {
            bottom: 0;
            left: 0;
            width: 20px;
            height: 2px;
        }

        .gufeng-corner.bottom-left::after {
            bottom: 0;
            left: 0;
            width: 2px;
            height: 20px;
        }

        .gufeng-corner.bottom-right {
            bottom: 8px;
            right: 8px;
        }

        .gufeng-corner.bottom-right::before {
            bottom: 0;
            right: 0;
            width: 20px;
            height: 2px;
        }

        .gufeng-corner.bottom-right::after {
            bottom: 0;
            right: 0;
            width: 2px;
            height: 20px;
        }

        /* ====== 设置栏 ====== */
        .gufeng-settings {
            display: flex;
            justify-content: flex-end;
            margin-bottom: 16px;
        }

        .gufeng-toggle-btn {
            background: var(--card-bg);
            border: 1px solid var(--border-color);
            padding: 6px 16px;
            cursor: pointer;
            font-size: 0.85em;
            font-family: inherit;
            color: var(--text-secondary);
            transition: all 0.3s ease;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .gufeng-toggle-btn:hover {
            background: var(--card-hover);
            color: var(--ink-primary);
        }

        .gufeng-toggle-btn.active {
            background: var(--card-active);
            border-color: var(--ink-primary);
            color: var(--ink-primary);
        }

        /* ====== 头部设计：卷轴标题风 ====== */
        .gufeng-header {
            padding: 12px 0;
            margin-bottom: 20px;
            display: flex;
            justify-content: space-between;
            align-items: flex-end;
            border-bottom: 1px solid var(--divider-color);
