        /* 标题装饰线 */
        .gufeng-header::before {
            content: '';
            position: absolute;
            bottom: -3px;
            left: 0;
            right: 0;
            height: 1px;
            background: var(--divider-color);
        }

        .gufeng-title {
            font-size: 1.6em;
            font-weight: 700;
            letter-spacing: 8px;
            color: var(--ink-primary);
            text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.1);
            position: relative;
        }

        /* 标题印章效果 */
        .gufeng-title::after {
            content: '记';
            position: absolute;
            right: -36px;
            top: 50%;
            transform: translateY(-50%) rotate(-5deg);
            font-size: 0.6em;
            color: var(--ink-accent);
            border: 1.5px solid var(--ink-accent);
            padding: 2px 4px;
            opacity: 0.7;
            letter-spacing: 0;
        }

        .gufeng-subtitle {
            font-size: 0.85em;
            color: var(--text-muted);
            letter-spacing: 2px;
        }

        /* ====== 日期滚动区 ====== */
        .gufeng-scroller {
            display: flex;
            overflow-x: auto;
            padding: 12px 4px 20px;
            margin-bottom: 16px;
            gap: 12px;
            scrollbar-width: none;
            mask-image: linear-gradient(to right, black 90%, transparent);
            -webkit-mask-image: linear-gradient(to right, black 90%, transparent);
        }

        .gufeng-scroller::-webkit-scrollbar {
            display: none;
        }

        /* 日期卡片：毛笔椭圆风格 */
        .gufeng-date-item {
            flex: 0 0 auto;
