            border: none;
            transition: all 0.3s ease;
            position: relative;
            opacity: 0.8;
            /* 不规则椭圆形状 - 模拟毛笔笔触 */
            border-radius: 50% 45% 55% 48% / 60% 52% 48% 55%;
            box-shadow:
