        /* ====== 事件列表区：古籍卷宗 ====== */
        .gufeng-list {
            padding: 12px 16px;
            min-height: 140px;
            background: var(--card-bg);
            border: 1px solid var(--divider-color);
            border-left: 3px solid var(--ink-primary);
        }

        /* 事件条目 */
        .gufeng-event {
            padding: 14px 16px;
            margin-bottom: 12px;
            position: relative;
            background: transparent;
            border-left: 2px solid transparent;
            transition: all 0.3s ease;
        }

        .gufeng-event:last-child {
            margin-bottom: 0;
        }

        .gufeng-event:hover {
            background: var(--card-hover);
            padding-left: 20px;
        }

        /* 事件印记 */
        .gufeng-event::before {
            content: '•';
            position: absolute;
            left: -16px;
            top: 14px;
            font-size: 1.2em;
            color: currentColor;
            opacity: 0.8;
        }

        .gufeng-event-meta {
            font-size: 0.78em;
            display: flex;
            align-items: center;
            gap: 10px;
            margin-bottom: 6px;
            letter-spacing: 1px;
        }

        .gufeng-event-title {
            font-size: 1.05em;
            line-height: 1.6;
            color: var(--text-primary);
        }

        .gufeng-event-desc {
            font-size: 0.88em;
            color: var(--text-secondary);
            margin-top: 8px;
            line-height: 1.7;
            padding: 10px 12px;
