        .gufeng-event-loc::before {
            content: '📍 ';
            font-size: 0.85em;
        }

        /* 事件类型样式 */
        .type-world {
            border-left-color: var(--c-world);
            color: var(--c-world);
        }

        .type-world .gufeng-event-meta {
