        }

        .type-user {
            border-left-color: var(--c-user);
            color: var(--c-user);
        }

        .type-user .gufeng-event-meta {
            color: var(--c-user);
        }

        .type-character {
            border-left-color: var(--c-char);
            color: var(--c-char);
        }

        .type-character .gufeng-event-meta {
            color: var(--c-char);
        }

        /* 空状态 */
        .gufeng-empty {
            font-size: 0.95em;
            color: var(--text-muted);
            text-align: center;
