    <script type="text/plain" id="calendar-raw-data">$1</script>

    <script>
        (function () {
            const container = document.getElementById('gufeng-calendar-container');
            const modeToggle = document.getElementById('gufeng-mode-toggle');
            const rawDataContainer = document.getElementById('calendar-raw-data');

            // === 缓存键名 ===
            const STORAGE_KEY_MODE = 'gufeng-calendar-dark-mode';

            // === 读取缓存的设置 ===
            let isDarkMode = localStorage.getItem(STORAGE_KEY_MODE) === 'true';

            // === 应用缓存的深色模式 ===
            if (isDarkMode) {
                container.classList.add('dark-mode');
                modeToggle.querySelector('.mode-icon').textContent = '☀️';
                modeToggle.querySelector('.mode-text').textContent = '朱批';
                modeToggle.classList.add('active');
            }

            // === 深色模式切换 ===
            modeToggle.addEventListener('click', () => {
                isDarkMode = !isDarkMode;
                container.classList.toggle('dark-mode', isDarkMode);
                modeToggle.querySelector('.mode-icon').textContent = isDarkMode ? '☀️' : '🌙';
                modeToggle.querySelector('.mode-text').textContent = isDarkMode ? '朱批' : '墨玉';
                modeToggle.classList.toggle('active', isDarkMode);
                localStorage.setItem(STORAGE_KEY_MODE, isDarkMode);
            });

            // === 日历数据解析 ===
            if (!rawDataContainer) return;
            const rawString = rawDataContainer.textContent.trim();

            const lines = rawString.split(/\r?\n/);
            const calendarData = [];
            let currentDayObj = null;

            lines.forEach(line => {
                line = line.trim();
                if (!line) return;
                if (line.startsWith('Date:')) {
                    const parts = line.replace('Date:', '').split('|').map(s => s.trim());
                    if (parts.length >= 1) {
                        currentDayObj = {
                            dateStr: parts[0],
                            dayName: parts[1] || '',
                            events: []
                        };
                        calendarData.push(currentDayObj);
                    }
                }
                else if (line.startsWith('Event:') && currentDayObj) {
                    const parts = line.replace('Event:', '').split('|').map(s => s.trim());
                    if (parts.length >= 5) {
                        currentDayObj.events.push({
                            type: parts[0],
                            title: parts[1],
                            desc: parts[2],
                            time: parts[3],
                            location: parts[4]
                        });
                    } else if (parts.length >= 4) {
                        currentDayObj.events.push({
                            type: parts[0],
                            title: parts[1],
                            desc: '',
                            time: parts[2],
                            location: parts[3]
                        });
                    }
                }
            });

            const scroller = document.getElementById('gufeng-scroller');
            const eventList = document.getElementById('gufeng-list');

            function getColorByType(type) {
                switch (type) {
                    case 'world': return 'var(--c-world)';
                    case 'major': return 'var(--c-major)';
                    case 'user': return 'var(--c-user)';
                    case 'character': return 'var(--c-char)';
                    default: return 'currentColor';
                }
            }

            function translateType(type) {
                switch (type.toLowerCase()) {
                    case 'world': return '天下';
                    case 'major': return '要务';
                    case 'user': return '私事';
                    case 'character': return '情谊';
                    default: return '杂事';
                }
            }

            // 转换为古式星期
            function toDayName(dayName) {
                const map = {
                    '星期一': '壹',
                    '星期二': '贰',
                    '星期三': '叁',
                    '星期四': '肆',
                    '星期五': '伍',
                    '星期六': '陆',
                    '星期日': '日',
                    'Mon': '壹',
                    'Tue': '贰',
                    'Wed': '叁',
                    'Thu': '肆',
                    'Fri': '伍',
                    'Sat': '陆',
                    'Sun': '日'
                };
                return map[dayName] || dayName;
            }

            function render() {
                scroller.innerHTML = '';
                calendarData.forEach((day, index) => {
                    const card = document.createElement('div');
                    card.className = `gufeng-date-item ${index === 0 ? 'active' : ''}`;

                    const dateParts = day.dateStr.split('/');
                    const dayNum = dateParts[dateParts.length - 1];
                    const displayDayName = toDayName(day.dayName);

                    let dotsHtml = '';
                    day.events.forEach(ev => {
                        const color = getColorByType(ev.type);
                        dotsHtml += `<div class="gufeng-dot" style="background-color: ${color}"></div>`;
                    });

                    card.innerHTML = `
                        <span class="gufeng-day-name">${displayDayName}</span>
                        <span class="gufeng-day-num">${dayNum}</span>
                        <div class="gufeng-dots">${dotsHtml}</div>
                    `;

                    card.onclick = () => {
                        scroller.querySelectorAll('.gufeng-date-item').forEach(c => c.classList.remove('active'));
                        card.classList.add('active');
                        card.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
                        renderEvents(day);
                    };
                    scroller.appendChild(card);
                });

                if (calendarData.length > 0) {
                    renderEvents(calendarData[0]);
                } else {
                    eventList.innerHTML = '<div class="gufeng-empty">尚无行程</div>';
                }
            }

            function renderEvents(dayData) {
                eventList.innerHTML = '';
                if (dayData.events.length === 0) {
                    eventList.innerHTML = '<div class="gufeng-empty">今日无事，可小憩片刻</div>';
                    return;
                }

                dayData.events.forEach(ev => {
                    const item = document.createElement('div');
                    item.className = `gufeng-event type-${ev.type}`;

                    let typeLabel = translateType(ev.type);

                    const descHtml = ev.desc ? `<div class="gufeng-event-desc">${ev.desc}</div>` : '';
                    item.innerHTML = `
                        <div class="gufeng-event-meta">
                            <span>${ev.time}</span>
                            <span>｜</span>
                            <span>${typeLabel}</span>
                        </div>
                        <div class="gufeng-event-title">${ev.title}</div>
                        ${descHtml}
                        <div class="gufeng-event-loc">${ev.location}</div>
                    `;
                    eventList.appendChild(item);
                });
            }

            render();
        })();
    </script>
</body>

</html>
