        </div>

        <div class="cal-header">
            <div class="cal-title">日程安排</div>
            <div class="cal-subtitle">小蛾子3.0 PRO</div>
        </div>

        <div class="date-scroller" id="app-scroller-v4"></div>
        <div class="event-list" id="app-list-v4"></div>
    </div>


    <script type="text/plain" id="calendar-raw-data-v4">$1</script>

    <script>
        (function () {
            // === 1. 主题切换 (v4) ===
            const app = document.getElementById('appCalendarV4');
            const icon = document.getElementById('appThemeIconV4');
            const STORAGE_KEY = 'app-calendar-theme-v4';

            function initTheme() {
                const savedTheme = localStorage.getItem(STORAGE_KEY);
                if (savedTheme === 'dark') {
                    app.classList.add('dark-mode');
                    icon.textContent = '☾';
                } else {
                    app.classList.remove('dark-mode');
                    icon.textContent = '☀';
                }
            }

            window.toggleAppThemeV4 = function() {
                app.classList.toggle('dark-mode');
                const isDark = app.classList.contains('dark-mode');
                icon.textContent = isDark ? '☾' : '☀';
                localStorage.setItem(STORAGE_KEY, isDark ? 'dark' : 'light');
            };
            initTheme();

            // === 2. 数据处理 ===
            const rawDataContainer = document.getElementById('calendar-raw-data-v4');
            if (!rawDataContainer) return;
            const rawString = rawDataContainer.textContent.trim();

            const lines = rawString.split(/\r?\n/);
            const calendarData = [];
            let currentDayObj = null;

            lines.forEach(line => {
                line = line.trim();
                if (!line) return;
                if (line.startsWith('Date:')) {
                    const parts = line.replace('Date:', '').split('|').map(s => s.trim());
                    if (parts.length >= 1) {
                        currentDayObj = {
                            dateStr: parts[0],
                            dayName: parts[1] || '',
                            events: []
                        };
                        calendarData.push(currentDayObj);
                    }
                } else if (line.startsWith('Event:') && currentDayObj) {
                    const parts = line.replace('Event:', '').split('|').map(s => s.trim());
                    if (parts.length >= 5) {
                        currentDayObj.events.push({
                            type: parts[0],
                            title: parts[1],
                            description: parts[2],
                            time: parts[3],
                            location: parts[4]
                        });
                    }
                }
            });

            // === 3. 渲染 ===
            const scroller = document.getElementById('app-scroller-v4');
            const eventList = document.getElementById('app-list-v4');

            function getTypeColor(type) {
                if (type === 'world') return 'var(--accent-world)';
                if (type === 'major') return 'var(--accent-major)';
                if (type === 'user') return 'var(--accent-user)';
                if (type === 'character') return 'var(--accent-char)';
                return '#ccc';
            }

            function render() {
                scroller.innerHTML = '';
                if (calendarData.length > 0) {
                    renderScroller(0);
                    renderEvents(calendarData[0]);
                } else {
                    eventList.innerHTML = '<div class="empty-state">暂无日程安排</div>';
                }
            }

            function renderScroller(activeIndex) {
                calendarData.forEach((day, index) => {
                    const card = document.createElement('div');
                    card.className = `date-card ${index === activeIndex ? 'active' : ''}`;

                    const dateParts = day.dateStr.split('/');
                    const dayNum = dateParts[dateParts.length - 1];

                    let dotsHtml = '';
                    day.events.forEach(ev => {
                        let color = getTypeColor(ev.type);
                        dotsHtml += `<div class="dot" style="background-color: ${color}"></div>`;
                    });

                    card.innerHTML = `
                        <span class="day-name">${day.dayName}</span>
                        <span class="day-num">${dayNum}</span>
                        <div class="event-dots">${dotsHtml}</div>
                    `;

                    card.onclick = () => {
                        const allCards = scroller.querySelectorAll('.date-card');
                        allCards.forEach(c => c.classList.remove('active'));
                        card.classList.add('active');
                        renderEvents(day);
                    };
                    scroller.appendChild(card);
                });
            }

            function renderEvents(dayData) {
                eventList.innerHTML = '';
                if (!dayData || dayData.events.length === 0) {
                    eventList.innerHTML = '<div class="empty-state">今日无待办事项，好好休息吧。</div>';
                    return;
                }

                dayData.events.forEach(ev => {
                    const details = document.createElement('details');
                    details.className = `event-details-card type-${ev.type}`;

                    let icon = '📍';
                    if (ev.type === 'world') icon = '🌍';
                    if (ev.type === 'major') icon = '🎉';
                    if (ev.type === 'user') icon = '📝';
                    if (ev.type === 'character') icon = '💕';

                    // 箭头改为 ›
                    details.innerHTML = `
                        <summary class="event-summary">
                            <div class="arrow-icon">›</div>
                            <div class="event-meta-row">
                                <span>${ev.time}</span>
                                <span>${ev.type.toUpperCase()}</span>
                            </div>
                            <div class="event-title">${ev.title}</div>
                            <div class="event-loc">${icon} ${ev.location}</div>
                        </summary>
                        <div class="event-description">
                            ${ev.description}
                        </div>
                    `;
                    eventList.appendChild(details);
                });
            }

            render();
        })();
    </script>
</body>
</html>
