    <div class="branch-selector">
        <!-- 主要改动：移除了下面的 'open' 属性，使其默认折叠 -->
        <details class="collapsible-container" id="collapsible-content">
            <summary class="summary-text" id="card-header">
                <div class="header-content">
                    <span class="footer-text">蛾摩拉的剧情构思……</span>
                    <button id="theme-toggle" title="切换主题"></button>
                </div>
            </summary>
            <div class="content-wrapper">
                <ul id="options-container"></ul>
            </div>
        </details>
