<div class="novel-header-container" id="novel-container">
    <style>
        /* 作用域变量定义 */
        .novel-header-container {
            /* === 白昼/默认模式 (Day Mode) === */
            /* 还原为之前的透明质感，保留极其微弱的中间渐变以维持结构感 */
            --novel-bg: linear-gradient(to bottom, transparent, rgba(125, 125, 125, 0.04), transparent);
            --novel-text: var(--SmartThemeBodyColor); /* 跟随酒馆全局文字颜色 */
