            --novel-border: rgba(125, 125, 125, 0.15);  /* 通用边框色 */
            --novel-tag-bg: transparent;

            /* 基础布局 */
            font-family: 'Playfair Display', 'Noto Serif SC', serif;
            color: var(--novel-text);
            background: var(--novel-bg);
            padding: 40px 20px 30px;
            margin: 25px 0;
            border-top: 1px solid var(--novel-border);
            border-bottom: 1px solid var(--novel-border);
            text-align: center;
            position: relative;
            animation: novelFadeIn 1s ease-out;
            transition: all 0.5s ease; /* 丝滑切换动画 */
            border-radius: 4px;
        }

        /* === 黑夜模式 (Night Mode) === */
        .novel-header-container.night-mode {
            /* 深邃蓝调，文字变白 */
            --novel-bg: linear-gradient(to bottom, rgba(20, 24, 40, 0), rgba(20, 24, 40, 0.85), rgba(20, 24, 40, 0));
            --novel-text: #e0e5f0;
            --novel-card-bg: rgba(255, 255, 255, 0.08); /* 提亮卡片背景 */
            --novel-border: rgba(173, 216, 230, 0.25);  /* 冰蓝边框 */
            --novel-tag-bg: rgba(0, 0, 0, 0.2);
            /* 强制覆盖子元素文字颜色 */
            color: #e0e5f0 !important;
        }

        /* 黑夜模式下的标题颜色强制变亮 */
        .novel-header-container.night-mode .novel-title {
            color: #fff !important;
            text-shadow: 0 0 10px rgba(173, 216, 230, 0.5);
        }

        /* 开关按钮 */
        .theme-toggle-btn {
            position: absolute;
            top: 10px;
            right: 15px;
            background: transparent;
            border: 1px solid var(--novel-border);
            color: var(--novel-text);
            width: 32px;
            height: 32px;
            border-radius: 50%;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.1em;
            opacity: 0.5;
            transition: all 0.3s ease;
            z-index: 10;
        }

        .theme-toggle-btn:hover {
            opacity: 1;
            background: var(--novel-card-bg);
            transform: rotate(15deg) scale(1.1);
        }

        /* 章节号 */
        .novel-chapter-num {
            font-family: 'Cinzel', 'Noto Serif SC', serif;
            font-size: 0.95em;
            letter-spacing: 2px;
            opacity: 0.6;
            margin-bottom: 6px;
            display: block;
            color: inherit;
        }

        /* 标题 */
        .novel-title {
            font-size: 1.7em;
            font-weight: 700;
            margin-bottom: 18px;
            letter-spacing: 1px;
            color: var(--SmartThemeHeaderColor, inherit);
            transition: color 0.5s ease;
        }

        /* 布局容器 */
        .novel-meta-single-row { display: flex; justify-content: center; gap: 15px; margin-bottom: 18px; flex-wrap: wrap; }
        .novel-meta-multi-row  { display: flex; flex-direction: column; align-items: center; gap: 10px; margin-bottom: 18px; }

        /* 元数据卡片 */
        .novel-meta-card {
            font-size: 0.8em;
            padding: 5px 12px;
            border: 1px solid var(--novel-border);
            border-radius: 4px;
            background: var(--novel-card-bg);
