            opacity: 0.9;
            color: inherit;
        }

        .novel-meta-label { font-size: 0.8em; opacity: 0.6; font-style: normal; font-weight: 600; }

        /* CP 样式 */
        .novel-cp-inline { display: flex; align-items: center; gap: 4px; }
        .novel-cp-row    { display: flex; justify-content: center; align-items: center; gap: 8px; flex-wrap: wrap; }
        .novel-cp-group {
            display: flex; align-items: center; gap: 4px; padding: 3px 10px;
