    <script>
        (function () {
            // === 1. 主题切换逻辑 ===
            const app = document.getElementById('ghostCalendarApp');
            const icon = document.getElementById('themeIcon');
            const STORAGE_KEY = 'ghost-calendar-theme';

            // 初始化主题
            function initTheme() {
                const savedTheme = localStorage.getItem(STORAGE_KEY);
                if (savedTheme === 'night') {
                    app.classList.add('night-mode');
                    icon.textContent = '☀'; // 如果是夜晚，显示太阳图标准备切换回白天
                } else {
                    app.classList.remove('night-mode');
                    icon.textContent = '☾'; // 如果是白天，显示月亮图标
                }
            }

            // 切换函数 (挂载到window以便onclick调用)
            window.toggleGhostTheme = function() {
                app.classList.toggle('night-mode');
                const isNight = app.classList.contains('night-mode');

                // 更新图标
                icon.textContent = isNight ? '☀' : '☾';

                // 保存状态
                localStorage.setItem(STORAGE_KEY, isNight ? 'night' : 'day');
            };

            // 执行初始化
            initTheme();


            // === 2. 数据解析与渲染逻辑 (保持原版逻辑) ===
            const rawDataContainer = document.getElementById('calendar-raw-data-switch');
            if (!rawDataContainer) return;
            const rawString = rawDataContainer.textContent.trim();

            const lines = rawString.split(/\r?\n/);
            const calendarData = [];
            let currentDayObj = null;

            lines.forEach(line => {
                line = line.trim();
                if (!line) return;
                if (line.startsWith('Date:')) {
                    const parts = line.replace('Date:', '').split('|').map(s => s.trim());
                    if (parts.length >= 1) {
                        currentDayObj = {
                            dateStr: parts[0],
                            dayName: parts[1] || '',
                            events: []
                        };
                        calendarData.push(currentDayObj);
                    }
                }
                else if (line.startsWith('Event:') && currentDayObj) {
                    const parts = line.replace('Event:', '').split('|').map(s => s.trim());
                    if (parts.length >= 5) {
                        currentDayObj.events.push({
                            type: parts[0],
                            title: parts[1],
                            description: parts[2],
                            time: parts[3],
                            location: parts[4]
                        });
                    }
                }
            });

            const scroller = document.getElementById('ghost-scroller-switch');
            const eventList = document.getElementById('ghost-list-switch');

            function getColorByType(type) {
                switch(type) {
                    case 'world': return 'var(--c-world)';
                    case 'major': return 'var(--c-major)';
                    case 'user': return 'var(--c-user)';
                    case 'character': return 'var(--c-char)';
                    default: return 'currentColor';
                }
            }

            function translateType(type) {
                switch(type.toLowerCase()) {
                    case 'world': return '世界';
                    case 'major': return '重要';
                    case 'user': return '日常';
                    case 'character': return '羁绊';
                    default: return '其他';
                }
            }

            function render() {
                scroller.innerHTML = '';
                // 默认高亮第一天（可能是不同日期，所以不能强行active index 0，这里简单处理为第一个）
                // 也可以根据真实日期比对，但这是模拟数据就算了
                calendarData.forEach((day, index) => {
                    const card = document.createElement('div');
                    card.className = `ghost-date-item ${index === 0 ? 'active' : ''}`;

                    const dateParts = day.dateStr.split('/');
                    const dayNum = dateParts[dateParts.length - 1];

                    let dotsHtml = '';
                    day.events.forEach(ev => {
                        const color = getColorByType(ev.type);
                        dotsHtml += `<div class="ghost-dot" style="background-color: ${color}"></div>`;
                    });

                    card.innerHTML = `
                        <span class="ghost-day-name">${day.dayName}</span>
                        <span class="ghost-day-num">${dayNum}</span>
                        <div class="ghost-dots">${dotsHtml}</div>
                    `;

                    card.onclick = () => {
                        scroller.querySelectorAll('.ghost-date-item').forEach(c => c.classList.remove('active'));
                        card.classList.add('active');
                        renderEvents(day);
                    };
                    scroller.appendChild(card);
                });

                if (calendarData.length > 0) renderEvents(calendarData[0]);
                else eventList.innerHTML = '<div class="ghost-empty">空空如也</div>';
            }

            function renderEvents(dayData) {
                eventList.innerHTML = '';
                if (dayData.events.length === 0) {
                    eventList.innerHTML = '<div class="ghost-empty">没有安排？好好休息吧</div>';
                    return;
                }

                dayData.events.forEach(ev => {
                    const details = document.createElement('details');
                    details.className = `ghost-event-details type-${ev.type}`;

                    let typeLabel = translateType(ev.type);

                    details.innerHTML = `
                        <summary class="ghost-event-summary">
                            <div class="ghost-event-meta">
                                <span>${ev.time}</span>
                                <span>•</span>
                                <span>${typeLabel}</span>
                            </div>
                            <div class="ghost-event-title">${ev.title}</div>
                            <div class="ghost-event-loc">@ ${ev.location}</div>
                        </summary>
                        <div class="ghost-event-desc">${ev.description}</div>
                    `;
                    eventList.appendChild(details);
                });
            }

            render();
        })();
    </script>
